from pathlib import Path
import re

root = Path('bybit_eu_swing_radar/backend')

# Research contract v3: reuse proven v2 context extraction but bind provenance
# to immutable raw cross-layer history and start a new prospective cohort.
(root / 'research/signal_context_freeze_v3.py').write_text('''"""Prospective Signal-Time Context Freeze v3 using immutable raw history.\n\nV1/V2 cohorts remain immutable. V3 admits only signals opened after the first\nappend-only Cross-Layer v2 raw-history capture and never reconstructs pre-v3\nsignals from later materialized state.\n"""\nfrom __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any, Iterable, Mapping\n\nfrom research.signal_context_freeze_v2 import (\n    CROSS_LAYER_MAX_AGE_SECONDS,\n    CROSS_LAYER_SPEC_VERSION,\n    MICROSTRUCTURE_ALIGNMENT_SPEC_VERSION,\n    STRATEGY_VERSION,\n    build_freeze_payload as _build_v2_payload,\n    cross_layer_context as _cross_layer_v2,\n)\n\nSPEC_VERSION = "signal-context-freeze-v3"\nHISTORY_FAMILY = "cross-layer-context-v2"\nHISTORY_SOURCE = "immutable_raw_history_v1"\n\n\ndef spec() -> dict[str, Any]:\n    return {\n        "version": SPEC_VERSION,\n        "strategy_version": STRATEGY_VERSION,\n        "research_only": True,\n        "label_blind": True,\n        "outcome_fields_read": False,\n        "context_only": True,\n        "live_strategy_mutated": False,\n        "promotion_allowed": False,\n        "execution_proof": False,\n        "source_layers": {\n            "cross_layer_context": CROSS_LAYER_SPEC_VERSION,\n            "microstructure_alignment": MICROSTRUCTURE_ALIGNMENT_SPEC_VERSION,\n        },\n        "cross_layer_storage_source": HISTORY_SOURCE,\n        "cross_layer_history_family": HISTORY_FAMILY,\n        "immutable_history_required": True,\n        "prospective_start_rule": "only signals opened_at >= first immutable Cross-Layer v2 raw-history captured_at",\n        "historical_backfill_allowed": False,\n        "v1_preserved": True,\n        "v2_preserved": True,\n        "temporal_contract": {\n            "cross_layer_rule": "latest immutable Cross-Layer v2 raw-history capture with captured_at <= signal opened_at",\n            "cross_layer_max_age_seconds": CROSS_LAYER_MAX_AGE_SECONDS,\n            "source_capture_time_safe": True,\n            "provider_availability_verified": False,\n            "provider_availability_note": "raw-history capture time prevents future-capture leakage but does not by itself prove every upstream provider field was available at source time",\n            "microstructure_rule": "existing preregistered alignment features use bucket_start < signal opened_at only",\n            "freeze_may_run_after_signal": True,\n            "source_payloads_are_copied_immutably_into_freeze_rows": True,\n        },\n        "principles": [\n            "no pre-v3 signal is admitted into the v3 cohort",\n            "v1 and v2 freeze rows remain immutable",\n            "no outcome/status/net-R/exit fields are selected from the journal",\n            "future cross-layer captures are structurally excluded by history lookup",\n            "provider availability is not overstated",\n            "microstructure remains optional and strictly pre-signal",\n            "no composite score or trade recommendation is emitted",\n        ],\n    }\n\n\ndef cross_layer_context(record: Mapping[str, Any] | None, *, opened_at: datetime, symbol: str) -> dict[str, Any]:\n    result = _cross_layer_v2(record, opened_at=opened_at, symbol=symbol)\n    result["history_source"] = HISTORY_SOURCE\n    result["history_family"] = HISTORY_FAMILY\n    result["history_payload_fingerprint"] = record.get("payload_fingerprint") if record else None\n    result["history_immutable"] = bool(record)\n    result["source_capture_time_safe"] = bool(record)\n    result["provider_availability_verified"] = False\n    return result\n\n\ndef build_freeze_payload(\n    signal: Mapping[str, Any],\n    *,\n    cross_layer_record: Mapping[str, Any] | None,\n    microstructure_feature: Mapping[str, Any] | None,\n    recorder_symbols: Iterable[str],\n    frozen_at: datetime | None = None,\n    source_commit_sha: str | None = None,\n) -> dict[str, Any]:\n    payload = _build_v2_payload(\n        signal,\n        cross_layer_record=cross_layer_record,\n        microstructure_feature=microstructure_feature,\n        recorder_symbols=recorder_symbols,\n        frozen_at=frozen_at,\n        source_commit_sha=source_commit_sha,\n    )\n    payload["spec_version"] = SPEC_VERSION\n    payload["cross_layer_context"] = cross_layer_context(\n        cross_layer_record,\n        opened_at=datetime.fromisoformat(str(payload["opened_at"]).replace("Z", "+00:00")),\n        symbol=str(payload["symbol"]),\n    )\n    payload["cross_layer_storage_source"] = HISTORY_SOURCE\n    return payload\n''')

# Derive API shape from v2 so schema/status behavior stays aligned, then replace
# only the temporal source with append-only history.
v2_api = (root / 'app/research_signal_context_freeze_v2_api.py').read_text()
v3_api = v2_api
v3_api = v3_api.replace('Signal-Time Context Freeze v2', 'Signal-Time Context Freeze v3')
v3_api = v3_api.replace('research.signal_context_freeze_v2 import', 'research.signal_context_freeze_v3 import')
v3_api = v3_api.replace('attach_signal_context_freeze_v2_research', 'attach_signal_context_freeze_v3_research')
v3_api = v3_api.replace('/v1/research/signal-context-freeze-v2/', '/v1/research/signal-context-freeze-v3/')
v3_api = v3_api.replace('signal freeze v2', 'signal freeze v3')
v3_api = v3_api.replace('pre_v2_count', 'pre_v3_count').replace('pre_v2_journal_signals_excluded', 'pre_v3_journal_signals_excluded')

start_re = re.compile(r'async def _prospective_start_at\(connection: asyncpg\.Connection\) -> datetime \| None:\n.*?\n\nasync def _load_cross_layer', re.S)
start_replacement = '''async def _prospective_start_at(connection: asyncpg.Connection) -> datetime | None:\n    try:\n        return await connection.fetchval(\n            """\n            SELECT MIN(captured_at)\n            FROM research_snapshot_history\n            WHERE research_family='cross-layer-context-v2'\n              AND spec_version=$1\n            """,\n            CROSS_LAYER_SPEC_VERSION,\n        )\n    except asyncpg.UndefinedTableError:\n        return None\n\n\nasync def _load_cross_layer'''
v3_api, n = start_re.subn(start_replacement, v3_api, count=1)
if n != 1:
    raise SystemExit('failed to replace v3 prospective start lookup')

load_re = re.compile(r'async def _load_cross_layer\(connection: asyncpg\.Connection, opened_at: datetime\) -> dict\[str, Any\] \| None:\n.*?\n\nasync def capture_current_batch', re.S)
load_replacement = '''async def _load_cross_layer(connection: asyncpg.Connection, opened_at: datetime) -> dict[str, Any] | None:\n    try:\n        row = await connection.fetchrow(\n            """\n            SELECT captured_at,source_commit_sha,payload,payload_fingerprint\n            FROM research_snapshot_history\n            WHERE research_family='cross-layer-context-v2'\n              AND spec_version=$1\n              AND captured_at <= $2\n            ORDER BY captured_at DESC LIMIT 1\n            """,\n            CROSS_LAYER_SPEC_VERSION,\n            opened_at,\n        )\n    except asyncpg.UndefinedTableError:\n        return None\n    if row is None:\n        return None\n    return {\n        "captured_at": row["captured_at"].isoformat(),\n        "source_commit_sha": row["source_commit_sha"],\n        "payload_fingerprint": row["payload_fingerprint"],\n        "payload": _decode(row["payload"]),\n    }\n\n\nasync def capture_current_batch'''
v3_api, n = load_re.subn(load_replacement, v3_api, count=1)
if n != 1:
    raise SystemExit('failed to replace v3 cross-layer history lookup')

v3_api = v3_api.replace(
    '"prospective_start_at": start_at.isoformat() if start_at else None,\n        "source_commit_sha": source_sha,',
    '"prospective_start_at": start_at.isoformat() if start_at else None,\n        "prospective_start_source": "immutable_raw_history_v1",\n        "cross_layer_lookup_source": "research_snapshot_history",\n        "source_commit_sha": source_sha,',
    1,
)
v3_api = v3_api.replace(
    '"prospective_start_at": start_at.isoformat() if start_at else None,\n        "source_commit_sha": os.getenv("RAILWAY_GIT_COMMIT_SHA") or None,',
    '"prospective_start_at": start_at.isoformat() if start_at else None,\n        "prospective_start_source": "immutable_raw_history_v1",\n        "cross_layer_lookup_source": "research_snapshot_history",\n        "source_commit_sha": os.getenv("RAILWAY_GIT_COMMIT_SHA") or None,',
    1,
)
(root / 'app/research_signal_context_freeze_v3_api.py').write_text(v3_api)

# Exact-SHA smoke: v3 must use stable immutable start boundary and never exceed
# its prospective journal population.
v2_smoke = (root / 'scripts/production_signal_context_freeze_v2_smoke.py').read_text()
v3_smoke = v2_smoke.replace('Freeze v2', 'Freeze v3').replace('freeze v2', 'freeze v3')
v3_smoke = v3_smoke.replace('FREEZE_V2', 'FREEZE_V3').replace('freeze-v2', 'freeze-v3')
v3_smoke = v3_smoke.replace('signal-context-freeze-v2', 'signal-context-freeze-v3')
v3_smoke = v3_smoke.replace('pre_v2_journal_signals_excluded', 'pre_v3_journal_signals_excluded')
v3_smoke = v3_smoke.replace('pre-v2 signal leaked into v2 freeze cohort', 'pre-v3 signal leaked into v3 freeze cohort')
v3_smoke = v3_smoke.replace('v2 frozen count exceeds prospective journal population', 'v3 frozen count exceeds prospective journal population')
v3_smoke = v3_smoke.replace('v1_preserved") is not True', 'v1_preserved") is not True or spec.get("v2_preserved") is not True')
v3_smoke = v3_smoke.replace(
    'if spec.get("historical_backfill_allowed") is not False or spec.get("v1_preserved") is not True or spec.get("v2_preserved") is not True:',
    'if spec.get("historical_backfill_allowed") is not False or spec.get("v1_preserved") is not True or spec.get("v2_preserved") is not True or spec.get("immutable_history_required") is not True:',
)
v3_smoke = v3_smoke.replace(
    'safe = {\n        "source_commit_sha": capture.get("source_commit_sha"),',
    'safe = {\n        "source_commit_sha": capture.get("source_commit_sha"),\n        "prospective_start_source": capture.get("prospective_start_source"),\n        "cross_layer_lookup_source": capture.get("cross_layer_lookup_source"),',
)
v3_smoke = v3_smoke.replace(
    'if capture.get("source_commit_sha") != expected_sha:',
    'if capture.get("prospective_start_source") != "immutable_raw_history_v1" or capture.get("cross_layer_lookup_source") != "research_snapshot_history":\n        print("FAIL v3 is not bound to immutable raw history")\n        return 1\n    if capture.get("source_commit_sha") != expected_sha:',
)
(root / 'scripts/production_signal_context_freeze_v3_smoke.py').write_text(v3_smoke)

# Main route attachment.
main_path = root / 'app/main.py'
main = main_path.read_text()
anchor = 'attach_signal_context_freeze_v2_research(app, require_api_key)\n'
addition = '''attach_signal_context_freeze_v2_research(app, require_api_key)\n\n# Research-only prospective Signal-Time Context Freeze v3. V1/V2 remain\n# immutable; V3 selects Cross-Layer v2 only from append-only raw history.\nfrom app.research_signal_context_freeze_v3_api import attach_signal_context_freeze_v3_research\n\nattach_signal_context_freeze_v3_research(app, require_api_key)\n'''
if 'attach_signal_context_freeze_v3_research' not in main:
    if anchor not in main:
        raise SystemExit('main v2 attach anchor missing')
    main = main.replace(anchor, addition, 1)
main_path.write_text(main)

# v3 tests.
(root / 'test_signal_context_freeze_v3.py').write_text('''from datetime import datetime, timedelta, timezone\n\nfrom research.signal_context_freeze_v3 import (\n    CROSS_LAYER_SPEC_VERSION, HISTORY_FAMILY, HISTORY_SOURCE, SPEC_VERSION,\n    build_freeze_payload, spec,\n)\n\nNOW = datetime(2026, 8, 19, 8, 30, tzinfo=timezone.utc)\n\n\ndef test_v3_contract_requires_immutable_history_and_preserves_prior_cohorts():\n    payload = spec()\n    assert payload["version"] == SPEC_VERSION == "signal-context-freeze-v3"\n    assert payload["source_layers"]["cross_layer_context"] == CROSS_LAYER_SPEC_VERSION == "cross-layer-context-shadow-v2"\n    assert payload["cross_layer_storage_source"] == HISTORY_SOURCE == "immutable_raw_history_v1"\n    assert payload["cross_layer_history_family"] == HISTORY_FAMILY == "cross-layer-context-v2"\n    assert payload["immutable_history_required"] is True\n    assert payload["historical_backfill_allowed"] is False\n    assert payload["v1_preserved"] is True and payload["v2_preserved"] is True\n    assert payload["temporal_contract"]["source_capture_time_safe"] is True\n    assert payload["temporal_contract"]["provider_availability_verified"] is False\n    assert payload["promotion_allowed"] is False\n\n\ndef test_v3_freeze_copies_history_fingerprint_without_score_mutation():\n    record = {\n        "captured_at": (NOW - timedelta(minutes=5)).isoformat(),\n        "source_commit_sha": "ctx",\n        "payload_fingerprint": "abc123",\n        "payload": {\n            "data_quality": "COMPLETE",\n            "layers": {"sector_rotation": {"status": "FRESH"}},\n            "symbols": [{"symbol": "BTCUSDC", "sector_rotation": {"state": "LEADING"}}],\n            "global_context": {},\n        },\n    }\n    payload = build_freeze_payload(\n        {\n            "id": 7, "signal_key": "sig-v3", "strategy_version": "0.7.3",\n            "signal_class": "STRICT", "symbol": "BTCUSDC", "side": "long",\n            "opened_at": NOW, "setup_type": "liquidity_sweep",\n        },\n        cross_layer_record=record, microstructure_feature=None, recorder_symbols=(),\n        frozen_at=NOW + timedelta(minutes=1), source_commit_sha="main",\n    )\n    cross = payload["cross_layer_context"]\n    assert payload["spec_version"] == SPEC_VERSION\n    assert payload["cross_layer_storage_source"] == HISTORY_SOURCE\n    assert cross["status"] == "FRESH"\n    assert cross["history_payload_fingerprint"] == "abc123"\n    assert cross["history_immutable"] is True\n    assert cross["source_capture_time_safe"] is True\n    assert cross["provider_availability_verified"] is False\n    assert payload["composite_score_emitted"] is False\n    assert payload["promotion_allowed"] is False\n''')

(root / 'test_signal_context_freeze_v3_routes.py').write_text('''from pathlib import Path\n\nROOT = Path(__file__).resolve().parent\n\n\ndef test_main_attaches_signal_context_freeze_v3_routes():\n    text = (ROOT / "app" / "main.py").read_text()\n    assert "from app.research_signal_context_freeze_v3_api import attach_signal_context_freeze_v3_research" in text\n    assert "attach_signal_context_freeze_v3_research(app, require_api_key)" in text\n\n\ndef test_v3_api_is_immutable_history_only_and_prospective():\n    text = (ROOT / "app" / "research_signal_context_freeze_v3_api.py").read_text()\n    for route in ("/v1/research/signal-context-freeze-v3/spec", "/v1/research/signal-context-freeze-v3/capture", "/v1/research/signal-context-freeze-v3/status"):\n        assert route in text\n    assert text.count("dependencies=[Depends(require_api_key)]") >= 3\n    assert "FROM research_snapshot_history" in text\n    assert "research_family='cross-layer-context-v2'" in text\n    assert "captured_at <= $2" in text\n    assert "SELECT MIN(captured_at)" in text\n    assert "research_cross_layer_context_snapshots" not in text\n    assert '"historical_backfill_allowed": False' in text\n    assert "pre_v3_journal_signals_excluded" in text\n    for forbidden in ("net_r", "gross_r", "exit_reason", "mfe", "mae"):\n        assert forbidden not in text.lower()\n''')

# V2 automatic capture is retired; it remains manually auditable.
Path('.github/workflows/signal-context-freeze-v2.yml').write_text('''name: Signal Context Freeze v2 (retired automatic)\n\non:\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: signal-context-freeze-v2\n  cancel-in-progress: true\n\njobs:\n  capture:\n    runs-on: ubuntu-latest\n    timeout-minutes: 10\n    env:\n      PRODUCTION_RADAR_API_BASE_URL: ${{ vars.PRODUCTION_RADAR_API_BASE_URL }}\n      PRODUCTION_RADAR_API_KEY: ${{ secrets.PRODUCTION_RADAR_API_KEY }}\n      EXPECTED_SHA: ${{ github.sha }}\n    steps:\n      - uses: actions/checkout@v7\n        with:\n          ref: ${{ github.sha }}\n      - uses: actions/setup-python@v7\n        with:\n          python-version: "3.12"\n      - name: Capture and verify retired Signal-Time Context Freeze v2 manually\n        working-directory: bybit_eu_swing_radar/backend\n        run: python scripts/production_signal_context_freeze_v2_smoke.py\n''')

Path('.github/workflows/signal-context-freeze-v3.yml').write_text('''name: Signal Context Freeze v3 Immutable History\n\non:\n  schedule:\n    - cron: "29 * * * *"\n  workflow_dispatch:\n  push:\n    branches: [main]\n    paths:\n      - "bybit_eu_swing_radar/backend/research/signal_context_freeze_v3.py"\n      - "bybit_eu_swing_radar/backend/app/research_signal_context_freeze_v3_api.py"\n      - "bybit_eu_swing_radar/backend/scripts/production_signal_context_freeze_v3_smoke.py"\n      - "bybit_eu_swing_radar/backend/app/main.py"\n      - ".github/workflows/signal-context-freeze-v3.yml"\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: signal-context-freeze-v3\n  cancel-in-progress: true\n\njobs:\n  capture:\n    runs-on: ubuntu-latest\n    timeout-minutes: 10\n    env:\n      PRODUCTION_RADAR_API_BASE_URL: ${{ vars.PRODUCTION_RADAR_API_BASE_URL }}\n      PRODUCTION_RADAR_API_KEY: ${{ secrets.PRODUCTION_RADAR_API_KEY }}\n      EXPECTED_SHA: ${{ github.sha }}\n    steps:\n      - uses: actions/checkout@v7\n        with:\n          ref: ${{ github.sha }}\n      - uses: actions/setup-python@v7\n        with:\n          python-version: "3.12"\n      - name: Capture and verify prospective Signal-Time Context Freeze v3\n        working-directory: bybit_eu_swing_radar/backend\n        run: python scripts/production_signal_context_freeze_v3_smoke.py\n''')
